import { fitWithin, placeWithin, resizeWithin } from './geometry'
import type { Note, NoteColor, NoteId, Point, Rect, Size } from './types'

export interface NotesState {
  readonly notes: readonly Note[]
  /** Highest z-index handed out so far; raising a note just takes the next one. */
  readonly topZ: number
  /** The reducer enforces the geometry rules, so it has to know how big the board is. */
  readonly board: Size
}

export type NotesAction =
  // The id is generated by the caller to keep the reducer pure.
  | { type: 'note/created'; id: NoteId; rect: Rect; color: NoteColor }
  | { type: 'note/moved'; id: NoteId; position: Point }
  | { type: 'note/resized'; id: NoteId; size: Size }
  | { type: 'note/removed'; id: NoteId }
  | { type: 'note/edited'; id: NoteId; text: string }
  | { type: 'note/recolored'; id: NoteId; color: NoteColor }
  | { type: 'note/raised'; id: NoteId }
  | { type: 'board/resized'; size: Size }

export const EMPTY_STATE: NotesState = {
  notes: [],
  topZ: 0,
  board: { width: 0, height: 0 },
}

export function notesReducer(state: NotesState, action: NotesAction): NotesState {
  switch (action.type) {
    case 'note/created': {
      const z = state.topZ + 1
      const note: Note = {
        id: action.id,
        rect: placeWithin(resizeWithin(action.rect, state.board), state.board),
        color: action.color,
        text: '',
        z,
      }
      return { ...state, notes: [...state.notes, note], topZ: z }
    }

    case 'note/moved':
      return mapNote(state, action.id, (note) => ({
        ...note,
        rect: placeWithin({ ...note.rect, ...action.position }, state.board),
      }))

    case 'note/resized':
      return mapNote(state, action.id, (note) => ({
        ...note,
        rect: resizeWithin({ ...note.rect, ...action.size }, state.board),
      }))

    case 'note/removed':
      return { ...state, notes: state.notes.filter((note) => note.id !== action.id) }

    case 'note/edited':
      return mapNote(state, action.id, (note) => ({ ...note, text: action.text }))

    case 'note/recolored':
      return mapNote(state, action.id, (note) => ({ ...note, color: action.color }))

    case 'note/raised': {
      const target = state.notes.find((note) => note.id === action.id)
      if (!target || target.z === state.topZ) return state
      const z = state.topZ + 1
      return { ...mapNote(state, action.id, (note) => ({ ...note, z })), topZ: z }
    }

    case 'board/resized': {
      const { size } = action
      if (size.width === state.board.width && size.height === state.board.height) return state
      return {
        ...state,
        board: size,
        notes: state.notes.map((note) => ({ ...note, rect: fitWithin(note.rect, size) })),
      }
    }

    default:
      return assertNever(action)
  }
}

function mapNote(state: NotesState, id: NoteId, update: (note: Note) => Note): NotesState {
  return {
    ...state,
    notes: state.notes.map((note) => (note.id === id ? update(note) : note)),
  }
}

function assertNever(action: never): never {
  throw new Error(`Unhandled action: ${JSON.stringify(action)}`)
}
